; paper.asm -- chapter 24: all the names at 29 T-states a byte
; generated by gen24.py
        INCLUDE "msx.inc"
        OUTPUT "paper.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
names   EQU $C400               ; the copy of the 768 names
dirty   EQU $C700               ; a mark for each of the 24 rows of names
px      EQU dirty + 24          ; the player's column of the map
tick    EQU dirty + 25          ; frames, counted
shown   EQU dirty + 26          ; the coins' metatile now: coin or sky
count   EQU dirty + 27          ; the frames left
next    EQU dirty + 28          ; late.asm's next screen, spin.asm's next drawing
wait    EQU dirty + 30          ; late.asm's wait into the paper, in turns of 30 T
PROW    EQU 9                   ; the player's row of the map
SKY     EQU 0
COIN    EQU 4
PLAYER  EQU 5
NCOINS  EQU 5
COINT   EQU 6                   ; the coin's first tile
; full.asm with the 768 names sent at 29 T-states a byte, OUTI and JP NZ.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the tiles' shapes
        ld hl, shapes
        ld c, VDP_DATA
        ld b, 112
        otir
        VRAM_WRITE $2000        ; and their colours
        ld hl, colours
        ld b, 112
        otir
        ld hl, dirty            ; the RAM is not cleared at power-on
        ld b, 24 + 8            ; (chapter 13): the dirty marks and VARS
.clr:   ld (hl), 0
        inc hl
        djnz .clr
        call expand             ; the map into the copy
        ld a, 1
        ld (px), a
        ld d, PROW
        ld e, a
        ld a, PLAYER
        call put                ; the player in his first place
        ld a, COIN
        ld (shown), a
        call send               ; the copy to the VDP, the display off
        VDP_REG 1, $C0          ; the display on
        in a, (VDP_CTRL)        ; a flag left from before, cleared
        ld a, 64
        ld (count), a
loop:   call frame              ; the end of the paper
m0:     call send               ; the copy to the VDP
m1:     call step               ; and the next frame's changes into it
        ld hl, count
        dec (hl)
        jr nz, loop
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret

; send: the 768 names of the copy to the VDP at 29 T-states a byte, safe while
; the paper is drawn (chapter 20)
send:   VRAM_WRITE $1800
        ld hl, names
        ld c, VDP_DATA
        ld d, 3
.page:  ld b, 0                 ; 256
.byte:  outi                    ; 18
        jp nz, .byte            ; 11
        dec d
        jr nz, .page
        ret

; step: the next frame's changes, made in the copy while the paper is drawn:
; the player a metatile on, the map put back where he was, and every
; sixteenth frame the coins shown or hidden
step:   ld a, (px)
        ld e, a
        ld d, PROW
        call under              ; A: the map's metatile where he was
        call put
        ld a, (px)
        inc a
        cp 15
        jr nz, .in
        ld a, 1                 ; from the right wall back to the left
.in:    ld (px), a
        ld e, a
        ld d, PROW
        ld a, PLAYER
        call put
        ld hl, tick
        inc (hl)
        ld a, (hl)
        and 15
        ret nz                  ; fifteen frames in sixteen, no more
        ld a, (shown)
        xor COIN ^ SKY
        ld (shown), a           ; coin or sky
        ld hl, coins
        ld b, NCOINS
.coin:  push bc
        ld d, (hl)
        inc hl
        ld e, (hl)
        inc hl
        push hl
        ld a, (shown)
        call put
        pop hl
        pop bc
        djnz .coin
        ret

; under: A = the map's metatile at row D, column E
under:  ld a, d
        add a, a
        add a, a
        add a, a
        add a, a                ; 16 x row
        add a, e
        ld c, a
        ld b, 0
        ld hl, map
        add hl, bc
        ld a, (hl)
        ret

; put: the metatile in A at row D, column E of the map, 0 to 11 and 0 to 15:
; its four names into the copy, and its two rows of names marked dirty
put:    push de
        add a, a
        add a, a                ; four names a metatile
        ld c, a
        ld b, 0
        ld hl, metas
        add hl, bc
        ex de, hl               ; DE: its names; H, L: row and column
        ld a, l
        add a, a
        ld c, a                 ; BC: 2 x column
        ld l, h
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; 64 x row: two rows of 32 names
        add hl, bc
        ld bc, names
        add hl, bc              ; HL: its top left name in the copy
        ex de, hl
        ldi
        ldi                     ; the top two names
        ld a, e
        add a, 30
        ld e, a
        jr nc, .low
        inc d
.low:   ldi
        ldi                     ; and the two below them
        pop de
        ld a, d
        add a, a                ; its first row of names
        ld l, a
        ld h, high dirty
        ld (hl), 1
        inc l
        ld (hl), 1              ; and the second: both dirty
        ret

; expand: the map's 192 metatiles into the copy of the names
expand: ld hl, map
        ld d, 0                 ; row
.row:   ld e, 0                 ; column
.col:   ld a, (hl)
        push hl
        call put
        pop hl
        inc hl
        inc e
        ld a, e
        cp 16
        jr nz, .col
        inc d
        ld a, d
        cp 12
        jr nz, .row
        ret
shapes:
        db $00, $00, $00, $00, $00, $00, $00, $00, $FF, $80, $80, $80, $FF, $08, $08, $08
        db $00, $22, $77, $FF, $00, $44, $00, $11, $00, $44, $00, $11, $00, $44, $00, $11
        db $20, $3F, $20, $20, $20, $3F, $20, $20, $04, $FC, $04, $04, $04, $FC, $04, $04
        db $00, $00, $03, $0F, $1F, $1F, $3F, $3F, $00, $00, $C0, $F0, $F8, $F8, $FC, $FC
        db $3F, $3F, $1F, $1F, $0F, $03, $00, $00, $FC, $FC, $F8, $F8, $F0, $C0, $00, $00
        db $07, $0F, $0D, $0F, $07, $03, $1F, $3F, $E0, $F0, $B0, $F0, $E0, $C0, $F8, $FC
        db $67, $67, $07, $06, $06, $06, $0E, $1E, $E6, $E6, $E0, $60, $60, $60, $70, $78
colours:
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $14, $14, $14, $14, $14, $14, $14, $14
        db $3F, $3F, $3F, $3F, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
        db $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F
        db $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
metas:                          ; sky, wall, ground, ladder, coin, player
        db 0, 0, 0, 0        ; sky
        db 1, 1, 1, 1        ; wall
        db 2, 2, 3, 3        ; ground
        db 4, 5, 4, 5        ; ladder
        db 6, 7, 8, 9        ; coin
        db 10, 11, 12, 13        ; player
map:                            ; 12 rows of 16 metatiles
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01
        db $01, $00, $00, $04, $00, $00, $00, $00, $00, $00, $00, $00, $04, $00, $00, $01
        db $01, $00, $02, $02, $02, $02, $03, $00, $00, $00, $02, $02, $02, $02, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $00, $00, $00, $00, $00, $00, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $00, $04, $00, $00, $00, $00, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $02, $02, $02, $02, $02, $00, $00, $01
        db $01, $00, $00, $04, $00, $00, $03, $00, $00, $00, $00, $00, $00, $00, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $00, $00, $00, $00, $00, $04, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $00, $00, $00, $00, $00, $00, $00, $01
        db $01, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
coins:  db 2, 3, 2, 12, 5, 9, 7, 3, 8, 13   ; row, column
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
